#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long pos[100000];
    long long total = 0;

    for (int i = 0; i < n; i++) {
        pos[i] = total;
        long long length;
        scanf("%lld", &length);
        total += length;
    }

    if (total % 2 != 0) {
        printf("N\n");
        return 0;
    }

    long long half = total / 2;
    int matches = 0;

    for (int i = 0; i < n; i++) {
        long long target = pos[i] + half;
        if (target >= total) target -= total;

        int left = 0, right = n - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (pos[mid] == target) {
                matches++;
                break;
            } else if (pos[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    printf("%c\n", matches >= 4 ? 'S' : 'N');
    return 0;
}
